mapper.select:
select event_id, event_name, event_type, start_time, end_time, location, 
       organizer, description, cover_image, display_position, 
       view_count, click_count, status, create_time, update_time
from event


        and event_id = #{eventId}


        and event_name like concat('%', #{eventName}, '%')


        and event_type = #{eventType}


        and status = #{status}


        and display_position = #{displayPosition}

